/* Strict independent parsing of the actual FR01 exports. Not Unity import or gameplay. */
#include "ufbx.h"
#include <math.h>
#include <stdio.h>
int main(int argc,char **argv){if(argc!=2)return 2;ufbx_load_opts o={0};o.strict=true;o.target_unit_meters=1;ufbx_error error;ufbx_scene *s=ufbx_load_file(argv[1],&o,&error);if(!s){char msg[2048];ufbx_format_error(msg,sizeof(msg),&error);fprintf(stderr,"%s",msg);return 1;}int valid=s->meshes.count>0&&s->bones.count==0&&s->anim_stacks.count==0;size_t vertices=0,triangles=0;double radius=0;for(size_t j=0;j<s->meshes.count;j++){ufbx_mesh *m=s->meshes.data[j];vertices+=m->num_vertices;triangles+=m->num_triangles;valid&=m->vertex_uv.exists&&m->vertex_normal.exists&&m->skin_deformers.count==0;for(size_t i=0;i<m->num_vertices;i++){ufbx_vec3 p=m->vertices.data[i];if(m->instances.count)p=ufbx_transform_position(&m->instances.data[0]->geometry_to_world,p);double r=sqrt(p.x*p.x+p.y*p.y+p.z*p.z);valid&=isfinite(r);if(r>radius)radius=r;}for(size_t i=0;i<m->vertex_normal.values.count;i++){ufbx_vec3 n=m->vertex_normal.values.data[i];double r=sqrt(n.x*n.x+n.y*n.y+n.z*n.z);valid&=isfinite(r)&&r>.98&&r<1.02;}}valid&=vertices>=3&&triangles>=1&&radius<45;printf("{\"vertices\":%zu,\"triangles\":%zu,\"maximum_radius_m\":%.9g,\"bones\":%zu,\"animation_stacks\":%zu,\"passed\":%s}\n",vertices,triangles,radius,s->bones.count,s->anim_stacks.count,valid?"true":"false");ufbx_free_scene(s);return valid?0:1;}
